171	impl AddPrompter for TerminalAddPrompter {
172	    fn multi_select(&mut self, prompt: &str, items: &[String], checked: &[bool]) -> Result<Vec<usize>, CliError> {
173	        let ticked: Vec<usize> = checked
174	            .iter()
175	            .enumerate()
176	            .filter(|(_, on)| **on)
177	            .map(|(index, _)| index)
178	            .collect();
179	        let picked = MultiSelect::new(prompt, items.to_vec())
180	            .with_default(&ticked)
181	            .with_help_message("Up/Down move, Space toggles, Right all, Left none, type to filter")
182	            .raw_prompt()?;
183	        Ok(picked.into_iter().map(|option| option.index).collect())
184	    }
185	
186	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
187	        let mut editor = tty::Editor::from_env();
188	        loop {
189	            let hint = match &editor {
190	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
191	                None => format!("{prompt} (Esc cancels)"),
192	            };
193	            let opens_editor = editor.is_some();
194	            let line = Text::new(&hint)
195	                .with_validator(move |line: &str| {
196	                    Ok(match Summary::new(line) {
197	                        Err(_) if !(opens_editor && line.is_empty()) => {
198	                            Validation::Invalid("the summary cannot be blank".into())
199	                        }
200	                        _ => Validation::Valid,
201	                    })
202	                })
203	                .prompt()?;
204	            if let Ok(summary) = Summary::new(&line) {
205	                return Ok(Some(summary));
206	            }
207	            // The validator lets an empty line through only when there is an editor to open.
208	            let Some(chosen) = editor.take() else { continue };
209	            match chosen.edit() {
210	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
211	                // The answers so far are kept: the summary is asked for inline instead.
212	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
213	            }
214	        }
215	    }
216	
217	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
218	        Ok(Confirm::new(prompt).with_default(default).prompt()?)
219	    }
220	}
