228	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
229	/// remainder default to patch), a summary unless one was given, then a review to confirm (a dry run writes nothing, so
230	/// it does not ask). Changed packages are listed
231	/// first and start ticked. `None` when the contributor declines the review or the editor saves nothing, having been
232	/// told nothing was written.
233	fn run_wizard(
234	    choices: &[Choice],
235	    summary: Option<Summary>,
236	    dry_run: bool,
237	    prompter: &mut impl AddPrompter,
238	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
239	    let answers = ask(choices, summary, dry_run, prompter)?;
240	    if answers.is_none() {
241	        prompt_line(tty::CANCELLED);
242	    }
243	    Ok(answers)
244	}
245	
246	fn ask(
247	    choices: &[Choice],
248	    summary: Option<Summary>,
249	    dry_run: bool,
250	    prompter: &mut impl AddPrompter,
251	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
252	    if choices.is_empty() {
253	        return Err(CliError::AddNoPackagesInWorkspace);
254	    }
255	
256	    let mut ordered: Vec<&Choice> = choices.iter().collect();
257	    ordered.sort_by_key(|choice| !choice.changed);
258	    let labels: Vec<String> = ordered
259	        .iter()
260	        .map(|choice| {
261	            if choice.changed {
262	                format!("{} (changed)", choice.name)
263	            } else {
264	                choice.name.clone()
265	            }
266	        })
267	        .collect();
268	    let checked: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
269	    let selected_indices = prompter.multi_select(
270	        "Packages in this change (Space toggles, Enter confirms, Esc cancels)",
271	        &labels,
272	        &checked,
273	    )?;
274	    if selected_indices.is_empty() {
275	        return Err(CliError::AddNoPackagesSelected);
276	    }
277	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
278	    let unticked = vec![false; selected_packages.len()];
279	
280	    let majors = prompter.multi_select(
281	        "Which are a MAJOR bump? (breaking changes only)",
282	        &selected_packages,
283	        &unticked,
284	    )?;
285	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
286	
287	    let minor_candidates: Vec<String> = selected_packages
288	        .iter()
289	        .enumerate()
290	        .filter(|(idx, _)| !major_set.contains(idx))
291	        .map(|(_, name)| name.clone())
292	        .collect();
293	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
294	        std::collections::HashSet::new()
295	    } else {
296	        let minors = prompter.multi_select(
297	            "Which are a MINOR bump? (the rest get PATCH)",
298	            &minor_candidates,
299	            &unticked[..minor_candidates.len()],
300	        )?;
301	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
302	    };
303	
304	    let entries: Vec<Entry> = selected_packages
305	        .iter()
306	        .enumerate()
307	        .map(|(idx, name)| Entry {
308	            name: name.clone(),
309	            severity: if major_set.contains(&idx) {
310	                Severity::Major
311	            } else if minor_set.contains(name) {
312	                Severity::Minor
313	            } else {
314	                Severity::Patch
315	            },
316	        })
317	        .collect();
318	
319	    let summary = match summary {
320	        Some(summary) => summary,
321	        None => match prompter.summary("Changelog summary")? {
322	            Some(summary) => summary,
323	            None => return Ok(None),
324	        },
325	    };
326	
327	    prompt_line(&review(&entries, &summary.0));
328	    if dry_run || prompter.confirm("Write this changeset?", true)? {
329	        Ok(Some((entries, summary)))
330	    } else {
331	        Ok(None)
332	    }
333	}
