377	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
378	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
379	fn create_changeset(
380	    dir: &std::path::Path,
381	    archive: &std::path::Path,
382	    text: &str,
383	    permit: &ApplyPermit,
384	    mut next_slug: impl FnMut() -> String,
385	) -> Result<String, CliError> {
386	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
387	    for _ in 0..64 {
388	        let filename = format!("{}.md", next_slug());
389	        if archived(archive, &filename)? {
390	            continue;
391	        }
392	        let path = dir.join(&filename);
393	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
394	            Ok(()) => return Ok(filename),
395	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
396	            Err(source) => {
397	                return Err(CliError::Io {
398	                    source,
399	                    path: Some(path),
400	                })
401	            }
402	        }
403	    }
404	    Err(CliError::Io {
405	        source: std::io::Error::new(
406	            std::io::ErrorKind::AlreadyExists,
407	            "no unused changeset filename found after 64 attempts",
408	        ),
409	        path: Some(dir.to_path_buf()),
410	    })
411	}
