422	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
423	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
424	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
425	    for _ in 0..64 {
426	        let filename = format!("{}.md", generate_human_slug());
427	        let path = dir.join(&filename);
428	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
429	            source,
430	            path: Some(path.clone()),
431	        })?;
432	        if !taken && !archived(archive, &filename)? {
433	            return Ok(filename);
434	        }
435	    }
436	    Err(CliError::Io {
437	        source: std::io::Error::new(
438	            std::io::ErrorKind::AlreadyExists,
439	            "no unused changeset filename found after 64 attempts",
440	        ),
441	        path: Some(dir.to_path_buf()),
442	    })
443	}
