462	
463	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
464	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
465	    let ts = std::time::SystemTime::now()
466	        .duration_since(std::time::UNIX_EPOCH)
467	        .map(|d| d.as_nanos() as u64)
468	        .unwrap_or(0);
469	
470	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
471	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
472	    let offset = (ts >> 10) % 8000;
473	    let idx = (count + offset) % 8000;
474	
475	    let a = adjectives[(idx % 20) as usize];
476	    let n = nouns[((idx / 20) % 20) as usize];
477	    let v = verbs[((idx / 400) % 20) as usize];
478	
479	    format!("{a}-{n}-{v}")
480	}
