    #[test]
    fn the_review_lists_each_bump_then_the_summary() {
        let entries = [("cargo/a", Severity::Minor), ("cargo/b", Severity::Patch)].map(|(name, severity)| Entry {
            name: name.to_owned(),
            severity,
        });
        assert_eq!(
            review(&entries, "Add v2 exports\n\n- faster\n"),
