1	//! The one contract for interactive prompts: where they may run, how they end, and how `$EDITOR` is used.
2	
3	use std::io::IsTerminal as _;
4	
5	use crate::cli::OutputFormat;
6	
7	/// Proof that this run may prompt; only [`Prompts::detect`] makes one.
8	pub struct Prompts(());
9	
10	impl Prompts {
11	    /// Prompts need a person at the terminal (stdin, and stderr where they draw) and a text run: `--format json` is for
12	    /// scripts and never prompts.
13	    pub fn detect(format: OutputFormat) -> Option<Self> {
14	        (format == OutputFormat::Text && std::io::stdin().is_terminal() && std::io::stderr().is_terminal())
15	            .then_some(Self(()))
16	    }
17	
18	    #[cfg(test)]
19	    pub fn for_tests() -> Self {
20	        Self(())
21	    }
22	}
23	
24	/// Printed whenever a prompt run ends without writing.
25	pub const CANCELLED: &str = "Cancelled, nothing written.";
26	
27	/// Exit status for a prompt cancelled with Esc or Ctrl-C: 130, as shells report SIGINT.
28	pub const CANCELLED_EXIT: u8 = 130;
29	
30	/// The editor named by `$VISUAL`, else `$EDITOR`.
31	pub struct Editor {
32	    variable: &'static str,
33	    command: String,
34	}
35	
36	/// Why the editor could not be used; its message is the warning to print.
37	#[derive(Debug, thiserror::Error)]
38	#[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
39	pub struct EditorUnusable {
40	    variable: &'static str,
41	    command: String,
42	    reason: String,
43	}
44	
45	impl Editor {
46	    /// An empty or blank setting is unset.
47	    pub fn from_env() -> Option<Self> {
48	        ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
49	            let command = std::env::var(variable).ok()?;
50	            (!command.trim().is_empty()).then_some(Self { variable, command })
51	        })
52	    }
53	
54	    /// `VISUAL` or `EDITOR`, whichever named it.
55	    pub fn variable(&self) -> &'static str {
56	        self.variable
57	    }
58	
59	    /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
60	    /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
61	    pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
62	        self.try_edit().map_err(|reason| EditorUnusable {
63	            variable: self.variable,
64	            command: self.command,
65	            reason,
66	        })
67	    }
68	
69	    fn try_edit(&self) -> Result<Option<String>, String> {
70	        let words =
71	            shell_words::split(&self.command).map_err(|error| format!("it does not split into words: {error}"))?;
72	        let Some((program, args)) = words.split_first() else {
73	            return Err("it names no program".to_owned());
74	        };
75	        let failed = |error: std::io::Error| error.to_string();
76	        let file = tempfile::Builder::new()
77	            .prefix("callisto-")
78	            .suffix(".txt")
79	            .tempfile()
80	            .map_err(failed)?;
81	        let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
82	        let status = crate::runner::child_command(program, &[], &[])
83	            .args(args)
84	            .arg(file.path())
85	            .stdout(std::io::stderr())
86	            .status()
87	            .map_err(|error| format!("`{program}` did not start: {error}"))?;
88	        if !status.success() {
89	            return Ok(None);
90	        }
91	        let saved = std::fs::read(file.path()).map_err(failed)?;
92	        String::from_utf8(saved)
93	            .map(Some)
94	            .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
95	    }
96	}
97	
98	#[cfg(unix)]
99	mod editor_owns_ctrl_c {
100	    use std::sync::atomic::{AtomicBool, Ordering};
101	    use std::sync::Arc;
102	
103	    use signal_hook::consts::SIGINT;
104	
105	    /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
106	    /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
107	    pub struct Guard(Arc<AtomicBool>);
108	
109	    pub fn enter() -> std::io::Result<Guard> {
110	        let default_action = Arc::new(AtomicBool::new(false));
111	        signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
112	        Ok(Guard(default_action))
113	    }
114	
115	    impl Drop for Guard {
116	        fn drop(&mut self) {
117	            self.0.store(true, Ordering::SeqCst);
118	        }
119	    }
120	}
121	
122	#[cfg(not(unix))]
123	mod editor_owns_ctrl_c {
124	    pub struct Guard;
125	
126	    pub fn enter() -> std::io::Result<Guard> {
127	        Ok(Guard)
128	    }
129	}
